BEGIN TRANSACTION;
INSERT OR IGNORE INTO resources (id, name, short_description, long_description) VALUES (1, 'Action Points', '', 'AP spent to perform actions in combat.');
INSERT OR IGNORE INTO resources (id, name, short_description, long_description) VALUES (2, 'Mana', '', 'Power resource used to cast spells and fuel supernatural effects.');
INSERT OR IGNORE INTO resources (id, name, short_description, long_description) VALUES (3, 'Health', '', 'Determines how long a creature stays conscious and combat-effective.');
INSERT OR IGNORE INTO resources (id, name, short_description, long_description) VALUES (4, 'Vitality', '', 'Determines how close a creature is to death.');
INSERT OR IGNORE INTO resources (id, name, short_description, long_description) VALUES (5, 'Concentration', '', 'Represents how well a creature holds together planned actions under pressure.');
INSERT OR IGNORE INTO resources (id, name, short_description, long_description) VALUES (6, 'Gold', '', 'Default currency unit used for equipment and services.');
INSERT OR IGNORE INTO defenses (id, name, short_description, long_description) VALUES (1, 'Deflection', '', 'Represents a character''s ability to deflect direct melee and ranged attacks.');
INSERT OR IGNORE INTO defenses (id, name, short_description, long_description) VALUES (2, 'Reflex', '', 'Represents a character''s ability to dodge area of effect attacks.');
INSERT OR IGNORE INTO defenses (id, name, short_description, long_description) VALUES (3, 'Endurance', '', 'Represents resistance to bodily harm, force, poison, and disease.');
INSERT OR IGNORE INTO defenses (id, name, short_description, long_description) VALUES (4, 'Mind', '', 'Represents strength of mind and resistance to mental attack.');
INSERT OR IGNORE INTO damage_origins (id, name, short_description, long_description) VALUES (1, 'Physical', '', 'Anything from the physical world not affected by magic.');
INSERT OR IGNORE INTO damage_origins (id, name, short_description, long_description) VALUES (2, 'Magical', '', 'Anything made with magical origin or affected by magic.');
INSERT OR IGNORE INTO damage_origins (id, name, short_description, long_description) VALUES (3, 'Necrotic', '', 'Exposure to undead or dark magic.');
