INSERT OR IGNORE INTO conditions (id, name, short_description, long_description) VALUES (1, 'Burning', '', 'A burning creature suffers ongoing fire damage until the flames are extinguished.');
INSERT OR IGNORE INTO conditions (id, name, short_description, long_description) VALUES (2, 'Poisoned', '', 'A poisoned creature is suffering from a toxin with penalties and duration based on the poison.');
INSERT OR IGNORE INTO conditions (id, name, short_description, long_description) VALUES (3, 'Prone', '', 'The creature crawls, ranged attackers suffer a penalty, and adjacent enemies gain an accuracy bonus.');
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (1, 'Bleed', '', 'The target continues to suffer damage over the following rounds until the bleeding stops.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (2, 'Cleave', '', 'The attack may hit one additional target adjacent to the primary target using the same roll.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (3, 'Cripple', '', 'The target cannot move on their next round.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (4, 'Freeze', '', 'Reduces Action Points for a number of rounds and can stack.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (5, 'Burning', '', 'The target is set ablaze and continues to suffer fire damage until extinguished.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (6, 'Infectious', '', 'If the effect gets through, the target immediately suffers a disease.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (7, 'Knockdown', '', 'The attack knocks the target prone.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (8, 'Necrotic', '', 'Deals separate tracked necrotic damage that reduces maximum Health.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (9, 'Penetrate', '', 'The attack can pass through the primary target and hit an additional target behind it.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (10, 'Revealing', '', 'The target is revealed and cannot hide.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (11, 'Stun', '', 'The target skips the entire round and takes no actions.', NULL);
INSERT OR IGNORE INTO effects (id, name, short_description, long_description, defense_id) VALUES (12, 'Turn Undead', '', 'If the target is Undead, that target cannot attack you.', NULL);
INSERT OR IGNORE INTO weapon_qualities (id, name, short_description, long_description) VALUES (1, 'Brutal', '', 'Scores a critical hit on the two highest possible damage rolls rather than only the highest.');
INSERT OR IGNORE INTO weapon_qualities (id, name, short_description, long_description) VALUES (2, 'Close Quarters', '', 'Ignores the normal accuracy penalty for being used while threatened in melee.');
INSERT OR IGNORE INTO weapon_qualities (id, name, short_description, long_description) VALUES (3, 'Concealed', '', 'Easy to hide on your person and harder to notice.');
INSERT OR IGNORE INTO weapon_qualities (id, name, short_description, long_description) VALUES (4, 'Quiet', '', 'Making an attack with this weapon will not make any sound.');
INSERT OR IGNORE INTO weapon_qualities (id, name, short_description, long_description) VALUES (5, 'Reach', '', 'You can attack creatures up to 2 hexes or grids away.');
INSERT OR IGNORE INTO weapon_qualities (id, name, short_description, long_description) VALUES (6, 'Versatile', '', 'Two-handed by default, but can also be used in one hand with a lower damage die.');
INSERT OR IGNORE INTO spell_schools (id, name, short_description, long_description) VALUES (1, 'Theoretical', '', 'Magic studied, understood, and shaped through knowledge, analysis, and discipline.');
INSERT OR IGNORE INTO spell_schools (id, name, short_description, long_description) VALUES (2, 'Zealous', '', 'Magic shaped by belief, devotion, conviction, and the powers that answer them.');
INSERT OR IGNORE INTO spell_schools (id, name, short_description, long_description) VALUES (3, 'Primal', '', 'Magic drawn from nature, instinct, spirits, and the living forces of the world.');
INSERT OR IGNORE INTO ranges (id, name, short_description, long_description, max_distance) VALUES (1, 'Adjacent', 'A', 'Most effective against targets in an adjacent hex.', 1);
INSERT OR IGNORE INTO ranges (id, name, short_description, long_description, max_distance) VALUES (2, 'Close', 'C', 'Most effective against targets within 2-4 hexes.', 4);
INSERT OR IGNORE INTO ranges (id, name, short_description, long_description, max_distance) VALUES (3, 'Medium', 'M', 'Most effective against targets within 5-7 hexes.', 7);
INSERT OR IGNORE INTO ranges (id, name, short_description, long_description, max_distance) VALUES (4, 'Long', 'L', 'Most effective against targets within 8-10 hexes.', 10);
INSERT OR IGNORE INTO ranges (id, name, short_description, long_description, max_distance) VALUES (5, 'Extreme', 'X', 'Most effective against targets within 11-13 hexes.', 13);
INSERT OR IGNORE INTO ranges (id, name, short_description, long_description, max_distance) VALUES (6, 'Reach', '', 'Touch or immediate melee reach.', NULL);
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (1, 'Damage & Healing', '', '', '%', '(x - 5) * 7');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (2, 'Max Carry Weight', '', '', 'kg', '(x * 10) + 45');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (3, 'Action Points', '', '', '', 'x + 6 - floor(x / 4)');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (4, 'Deflection', '', '', '', 'x');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (5, 'Health', '', '', 'x Level', 'x + 5');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (6, 'Vitality', '', '', 'x Health', '3 + floor(x / 3)');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (7, 'Accuracy', '', '', '', 'x + 2');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (8, 'Crit Dice', '', '', '', '2 * ceil(x / 2.0) + 2');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (9, 'Potency', '', '', '', 'x + 2');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (10, 'Bestiary Progression', '', '', '%', 'x * 3');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (11, 'Mana Generation', '', '', '', 'floor(x / 2)');
INSERT OR IGNORE INTO modifiers (id, name, short_description, long_description, value_label, expression) VALUES (12, 'Concentration', '', '', '', 'ceil(x / 2.0)');
INSERT OR IGNORE INTO attributes (id, name, short_description, long_description, modifier_id_1, modifier_value_1, modifier_id_2, modifier_value_2, min_value, max_value) VALUES (1, 'Might', '', 'Might reflects raw force. It is the strength behind a crushing blow, the power needed to haul equipment across a battlefield, and the bodily force that lets a character impose themselves on the world.', 1, 0, 2, 0, 1, 10);
INSERT OR IGNORE INTO attributes (id, name, short_description, long_description, modifier_id_1, modifier_value_1, modifier_id_2, modifier_value_2, min_value, max_value) VALUES (2, 'Dexterity', '', 'Dexterity measures speed, balance, flexibility, and bodily control. It governs how quickly you can act, how easily you avoid incoming attacks, and how sharply your body reacts to sudden danger.', 3, 0, 4, 0, 1, 10);
INSERT OR IGNORE INTO attributes (id, name, short_description, long_description, modifier_id_1, modifier_value_1, modifier_id_2, modifier_value_2, min_value, max_value) VALUES (3, 'Constitution', '', 'Constitution measures bodily resilience. It is the deep reserve that lets a character remain standing, survive blood loss, and hold together when the body is pushed beyond what should be survivable.', 5, 0, 6, 0, 1, 10);
INSERT OR IGNORE INTO attributes (id, name, short_description, long_description, modifier_id_1, modifier_value_1, modifier_id_2, modifier_value_2, min_value, max_value) VALUES (4, 'Perception', '', 'Perception measures awareness and precision. It is the ability to notice a weakness in an enemy''s stance, recognize danger before it strikes, and place attacks exactly where they matter most.', 7, 0, 8, 0, 1, 10);
INSERT OR IGNORE INTO attributes (id, name, short_description, long_description, modifier_id_1, modifier_value_1, modifier_id_2, modifier_value_2, min_value, max_value) VALUES (5, 'Intelligence', '', 'Intelligence reflects memory, reason, and applied thought. It is the attribute behind clever planning, understanding systems, and shaping knowledge into something useful.', 9, 0, 10, 0, 1, 10);
INSERT OR IGNORE INTO attributes (id, name, short_description, long_description, modifier_id_1, modifier_value_1, modifier_id_2, modifier_value_2, min_value, max_value) VALUES (6, 'Resolve', '', 'Resolve reflects inner drive, self-control, and force of spirit. It is what lets a person stay focused under pressure, endure fear, and continue acting when lesser people would falter.', 11, 0, 12, 0, 1, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (1, 'Animal Handling', '', 'Calming wild animals. Training, guiding, and caring for domestic animals and companions.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (2, 'Athletics', '', 'Lifting, climbing, swimming, running, jumping, pushing, and other feats of physical exertion.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (3, 'Command', '', 'Issuing orders, coordinating allies, and asserting authority in tense situations.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (4, 'Craft', '', 'Creating, maintaining, and repairing structures, tools, mixtures, and devices.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (5, 'Insight', '', 'Reading motives, recognizing patterns in behavior, and understanding what people are really feeling or intending.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (6, 'Investigation', '', 'Searching, noticing hidden things, examining scenes, and identifying weaknesses in plans, structures, or security.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (7, 'Lore', '', 'Knowledge of history, magic, religion, cultures, creatures, and the wider world.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (8, 'Medicine', '', 'Treating wounds and injuries, diagnosing disease and poison, and understanding bodily harm.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (9, 'Navigation', '', 'Finding your way across land or sea, planning routes, and keeping direction in unfamiliar places.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (10, 'Sleight of Hand', '', 'Picking locks, handling delicate mechanisms, concealing small objects, and performing precise hand-work.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (11, 'Society', '', 'Understanding customs, class, law, trade, and how groups and institutions operate.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (12, 'Speech', '', 'Persuading, deceiving, inspiring, negotiating, and otherwise influencing people through words.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (13, 'Stealth', '', 'Moving quietly, hiding yourself, masking your presence, and avoiding notice.', 0, 10);
INSERT OR IGNORE INTO skills (id, name, short_description, long_description, min_rank, max_rank) VALUES (14, 'Survival', '', 'Finding shelter, water, and food, tracking creatures, enduring the wilds, and handling environmental dangers.', 0, 10);
