INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (1, 'Good Natured', 'Race', '', 'Your kind-hearted and altruistic nature inspires and empowers your companions. When you assist another character, add your full relevant skill instead of half.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (2, 'Unyielding', 'Race', '', 'Your people are shaped by hardship and do not break easily. When you suffer Trauma, you do not suffer the extra Concentration loss from it.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (3, 'Social Beings', 'Race', '', 'High Elves naturally carry status and legitimacy in the eyes of many cultures. You gain +2 Renown, representing your higher standing within societies. Individual people may still feel however they wish about you.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (4, 'Runic Destiny', 'Race', '', 'From the moment of birth, every Dwarf bears a rune etched into their body, signifying clan, heritage, and fate. Choose one of the following runes:
Explorer''s Rune - Whenever you roll on a loot table, roll twice and choose the outcome.
Magister''s Rune - You know one spell for free.
Artisan''s Rune - You gain +2 on tests when using something you made yourself.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (5, 'Nimble Escape', 'Race', '', 'Your small frame and quick instincts make it difficult to pin you down. When moving out of melee with only one opponent threatening you, the extra AP cost does not apply.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (6, 'From Fire and Flame', 'Race', '', 'Forged in the heart of a volcano, your body grows magical obsidian patches. Roll a random location at character creation. That location is immune to damage while the obsidian patch remains. If that location suffers 2 Trauma, the patch is destroyed. It regrows after a week, when your Vitality is reset.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (7, 'Forest Child', 'Race', '', 'Living in harmony with nature, your diet is strictly herbivorous. You cannot safely eat meat; if you do, your Max Health is reduced by 25% until you have had a full night''s rest. You are immune to disease, and all other food gives you double benefit.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (8, 'We Endure', 'Race', '', 'Life is harsh, and your people are shaped by enduring it. During each full rest, you may either heal one additional Injury or reduce the duration of one disease by an additional step.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (9, 'Soulless', 'Race', '', 'Though still fully living people, Husk-Folk have been touched by necrosis so deeply that it no longer harms them as it does others. You are immune to necrotic damage. Instead, you heal the full amount of necrotic damage that would have been inflicted upon you.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (10, 'Circle of Life', 'Homeland', '', 'Nothing Wasted. You know how to make use of what nature gives and what it takes.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (11, 'Proper Bearing', 'Homeland', '', 'Your upbringing in a refined kingdom grants you the manners and expectations of civilized life. In formal settings, you are treated with the respect due to proper station unless you give others reason not to.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (12, 'Frostborn', 'Homeland', '', 'You can increase your Survival rating by 1.5 when it comes to exposure to cold weather.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (13, 'Desert Adventurer', 'Homeland', '', 'You can increase your Survival rating by 1.5 when it comes to exposure to hot weather. You can go an hour longer for every stage of Thirst and hot weather does not halve it.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (14, 'No Safe Roads', 'Homeland', '', 'Travel-related rules will favor your experience once those systems are in place.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (15, 'Born to Fight', 'Homeland', '', 'Once per scene, you can completely ignore one attack that targets you.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (16, 'Looter', 'Homeland', '', 'Whenever you successfully salvage an area, you also gain a free roll on the Oddities and Valuables table.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (17, 'Animal Friend', 'Homeland', '', 'When you encounter a creature with the Beast tag, it will never attack you on sight. Also gain 1 reroll on all Animal Handling tests.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (18, 'Wanderer', 'Homeland', '', 'You can become Well-Rested even when sleeping in rough conditions that would normally prevent it.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (19, 'Survivor', 'Homeland', '', 'Necrotic damage cannot put you in a coma.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (20, 'Scorched Resourcefulness', 'Homeland', '', 'Foraging becomes easier anywhere.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (21, 'Military Training', 'Background', '', 'During combat, you gain 1 additional AP each turn that can only be spent on movement.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (22, 'Underhanded', 'Background', '', 'You do not need lockpicks in order to pick a lock.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (23, 'Deep Cover', 'Background', '', 'Your Renown is increased while you are undercover or disguised.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (24, 'Courtly Privilege', 'Background', '', 'You are accustomed to status, ceremony, and access. In appropriate civilized settings, you can secure basic hospitality or an audience that others might need to work harder to obtain.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (25, 'Simple Living', 'Background', '', 'Food and shelter you provide can support one additional person.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (26, 'Educated', 'Background', '', 'First encounter with a creature gives bonus Bestiary', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (27, 'Sanctified Presence', 'Background', '', 'Followers of your faith tend to treat you as one of their own unless given reason not to.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (28, 'Crowd Favorite', 'Background', '', 'People are more willing to feed, host, or hear you out after a performance.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (29, 'Efficient Worker', 'Background', '', 'Crafting uses fewer resources.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (30, 'Hardened Routine', 'Background', '', 'During each full rest, you may also remove 1 Fatigue if you have no remaining source causing it.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (31, 'Trailblazer', 'Background', '', 'Navigation becomes easier when you are leading the route.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (32, 'Haggle for a Living', 'Background', '', 'You can reroll 1d20 when browsing, and always gain a 10% discount.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (33, 'Home at Sea', 'Background', '', 'You can reroll 1d20 on Navigation tests while at sea. You also always gain Well-Rested when sleeping on a ship.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (34, 'Arena Instinct', 'Background', '', 'The first time each combat you would become Prone, you may ignore it.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (35, 'Forager', 'Background', '', 'Foraging takes less time for you.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (36, 'Wise Counsel', 'Background', '', 'When you take time to advise another character, their next relevant test becomes easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (37, 'Beast Handler', 'Background', '', 'You gain an Animal Handling perk.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (38, 'Trained to Kill', 'Background', '', 'Survival tests when tracking Dragons become easier. You may reroll 1d20 on every damaging attack against a Dragon. After killing a Dragon, local villages celebrate you as a hero and you sleep, drink, and eat for free for the next 3 days.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (39, 'Secluded', 'Background', '', 'You require less comfort to become Well-Rested and are less affected by long periods without company.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (40, 'Weapon Proficiency', 'Weapon', '', 'Requirement: Level 2\\n\\nChoose one weapon type. You gain access to that weapon''s Proficiency attacks.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (41, 'Weapon Expertise', 'Weapon', '', 'Requirement: Weapon Proficiency with the chosen weapon, Level 10\\n\\nChoose one weapon type in which you already have Weapon Proficiency. You gain access to that weapon''s Expertise attacks.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (42, 'Weapon Mastery', 'Weapon', '', 'Requirement: Weapon Expertise with the chosen weapon, Level 15\\n\\nChoose one weapon type in which you already have Weapon Expertise. You gain access to that weapon''s Mastery attacks.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (43, 'Quick Swap', 'Weapon', '', 'Requirement: Weapon Proficiency, Dexterity 6\\n\\nOnce per round, you may swap loadouts or ready a different weapon as a free action.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (44, 'Master at Arms', 'Weapon', '', 'Requirement: Quick Swap, Level 4\\n\\nYou gain one additional weapon loadout.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (45, 'Dual Wielder', 'Weapon', '', 'Requirement: Dexterity 6\\n\\nWhen fighting with a one-handed weapon in each hand, the first off-hand attack you make each round costs 1 less AP.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (46, 'Duelist', 'Weapon', '', 'Requirement: Dexterity 7, Weapon Proficiency with a one-handed melee weapon\\n\\nWhile wielding a single one-handed melee weapon and no shield, gain +1 Deflection.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (47, 'Riposte', 'Weapon', '', 'Requirement: Duelist, Level 5\\n\\nThe first time each round a creature misses you with a melee attack, your next melee attack against that creature gains +1 Accuracy and deals 10% more damage.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (48, 'Accurate', 'Weapon', '', 'Requirement: Perception 6\\n\\nOnce each round, you may re-roll 1d20 on an attack made with a weapon you have proficiency in.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (49, 'Center of Mass', 'Weapon', '', 'Requirement: Accurate, Level 4\\n\\nWhen you make a ranged attack against a creature within the weapon''s normal range, gain +1 Accuracy.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (50, 'Bull''s Eye', 'Weapon', '', 'Requirement: Center of Mass, Level 7\\n\\nThe first ranged attack you make each round gains +1 Crit Die size.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (51, 'Giant''s Grip', 'Weapon', '', 'Requirement: Might 7\\n\\nYou can wield a two-handed melee weapon in one hand for the purpose of carrying or readying it, but you still need two hands to use its attacks unless another rule says otherwise.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (52, 'Hold the Line', 'Weapon', '', 'Requirement: Might 6, Constitution 6\\n\\nCreatures provoke 1 additional AP to move out of your Reach.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (53, 'Heavy Armor Master', 'Weapon', '', 'Requirement: Might 7, Constitution 6, Level 5\\n\\nWhile in Heavy Load, gain +1 Physical DT.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (54, 'Mage Slayer', 'Weapon', '', 'Requirement: Resolve 6, Level 5\\n\\nWhen you damage a creature that currently has Concentration, reduce its Concentration by 1. This can only happen once per turn.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (55, 'Fast Hands', 'Weapon', '', 'Requirement: Dexterity 6\\n\\nThe first Interact action you take each round costs 1 less AP, to a minimum of 1.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (56, 'Magical Student', 'Magic', '', 'Requirement: Intelligence 6, Lore 2\\n\\nLearn Theoretical spells through study and observation, gaining permanent access to all spells recorded in your spellbook without needing preparation.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (57, 'Patronage', 'Magic', '', 'Requirement: Resolve 6\\n\\nGain spells from any school through deals, sacrifices, and narrative events, with your power shaped and potentially altered by your patron.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (58, 'Conviction', 'Magic', '', 'Requirement: Resolve 6, Speech 2 or Lore 2\\n\\nGain a fixed set of Zealous spells based on your chosen belief or drive, changing only if your conviction fundamentally shifts.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (59, 'Ritualist', 'Magic', '', 'Requirement: Resolve 6, Survival 2 or Lore 2\\n\\nSelect a limited number of Primal spells after performing a ritual, allowing you to change your available spells during a full rest.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (60, 'Innate Power', 'Magic', '', 'Requirement: Resolve 6\\n\\nChoose a magical keyword, such as Fire, Illusion, or Necrotic. You learn matching spells from any school, with a limited number of permanently known spells that grows as you level.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (61, 'Font of Mana', 'Magic', '', 'Requirement: Resolve 7\\n\\nIncrease your maximum Mana by 2.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (62, 'Quiet Casting', 'Magic', '', 'Requirement: Any magical identity perk, Level 3\\n\\nTests made to notice your spellcasting become harder unless the spell is especially loud, bright, or destructive.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (63, 'Mind Fortress', 'Magic', '', 'Requirement: Resolve 7, Level 4\\n\\nGain +1 Concentration.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (64, 'Spellsword', 'Magic', '', 'Requirement: Any magical identity perk, Weapon Proficiency, Level 4\\n\\nChoose one weapon type you have Weapon Proficiency with. That weapon counts as a casting focus for you, and the first time each round you deal damage with it you gain 1 Mana.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (65, 'Pyromaniac', 'Magic', '', 'Requirement: Ability to deal Fire damage\\n\\nYou deal 10% more damage against targets that are on fire. If a single attack or spell affects more than one target that is on fire, increase the damage by an additional 10% for each extra burning target, up to 30% total.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (66, 'Fire Starter', 'Magic', '', 'Requirement: Ability to deal Fire damage\\n\\nThe first time each round you deal Fire damage, you may re-roll 1d20 on one Fire-related damage or effect roll tied to that action. If the table does not use such a roll, that attack or spell instead deals 10% more damage.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (67, 'Cryo-Expert', 'Magic', '', 'Requirement: Ability to deal Freeze damage or use Ice magic\\n\\nCreatures affected by your Ice or Freeze effects are easier to keep controlled. The first time each round you inflict Freeze, the target also loses 1 AP.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (68, 'Necrosis', 'Magic', '', 'Requirement: Ability to deal Necrotic damage\\n\\nWhen you deal Necrotic damage, ignore 1 Necrotic DT.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (69, 'Deliberate Strikes', 'Magic', '', 'Requirement: Perception 6\\n\\nWhenever one of your attacks scores a critical hit, gain 1 Mana.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (70, 'Crits on Crits', 'Magic', '', 'Requirement: Deliberate Strikes, Perception 8, Level 8\\n\\nWhen one of your Crit Dice rolls its highest value, roll one additional Crit Die of the same size and add it. Dice generated by this perk cannot generate further Crit Dice.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (71, 'Bloodlust', 'Magic', '', 'Requirement: Might 6 or Resolve 6\\n\\nWhen you deal 5 or more HP damage with a single attack or spell, gain 1 Mana. If you deal 10 or more HP damage, gain 2 Mana instead. You cannot gain more than 2 Mana per turn from this perk.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (72, 'Hemomancy', 'Magic', '', 'Requirement: Resolve 6, Level 4\\n\\nWhen you suffer 5 or more HP damage from a single source, gain 1 Mana. If you suffer 10 or more HP damage, gain 2 Mana instead. You cannot gain more than 2 Mana per turn from this perk.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (73, 'War Cry', 'Leadership and Social', '', 'Requirement: Command 2\\n\\nOnce per scene, when combat begins, one ally who can hear you gains +1 AP on their first turn.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (74, 'Born Leader', 'Leadership and Social', '', 'Requirement: Command 3, Resolve 6\\n\\nWhen you Assist an ally, they may use your full Command rank instead of half your skill bonus.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (75, 'Commanding Presence', 'Leadership and Social', '', 'Requirement: Born Leader, Command 5, Level 6\\n\\nThe first time each scene you give an ally a direct order in a tense situation, their next relevant test becomes easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (76, 'Terrifying Presence', 'Leadership and Social', '', 'Requirement: Might 6 or Command 2\\n\\nWhen you try to intimidate a creature, you may use Might instead of Speech if your threat is based on force or physical menace.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (77, 'Read the Room', 'Leadership and Social', '', 'Requirement: Insight 2\\n\\nWhen you enter a social scene, you may ask the GM for the dominant mood, pressure, or tension in the room.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (78, 'Body Language', 'Leadership and Social', '', 'Requirement: Insight 3\\n\\nTests to notice lies, fear, hidden hostility, or hesitation become easier for you.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (79, 'Voice of Reason', 'Leadership and Social', '', 'Requirement: Speech 2\\n\\nOnce per scene, when you try to calm panic, defuse conflict, or stop a rash decision, re-roll 1d20 on the test.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (80, 'Barter', 'Leadership and Social', '', 'Requirement: Speech 2, Society 2\\n\\nWhen you negotiate prices, gain a 10% discount on ordinary legal goods unless a stronger rule already applies.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (81, 'Diplomat', 'Leadership and Social', '', 'Requirement: Speech 3, Society 3\\n\\nIn formal negotiations, the first failed Speech or Society test you make each scene may be re-rolled.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (82, 'Inner Circle', 'Leadership and Social', '', 'Requirement: Society 2\\n\\nIn courts, guilds, temples, or other structured groups, you are better at identifying who really holds influence.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (83, 'Leveraging Status', 'Leadership and Social', '', 'Requirement: Society 3\\n\\nIf you have positive Renown in the current culture or faction, gain +2 on your first related social test each scene.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (84, 'Black Market', 'Leadership and Social', '', 'Requirement: Society 2 or Stealth 2\\n\\nTests made to find illegal, hidden, or restricted goods become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (85, 'I Belong Here', 'Leadership and Social', '', 'Requirement: Society 2 or Stealth 2\\n\\nWhen trying to pass as part of a crowd, workplace, or social function, the first test to challenge your presence becomes harder.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (86, 'Tricks of the Trade', 'Knowledge and Craft', '', 'Requirement: Craft 2\\n\\nChoose one field of craft such as alchemy, smithing, bowyering, tailoring, tinkering, or writing. Tests in that field become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (87, 'Traveling Craftsman', 'Knowledge and Craft', '', 'Requirement: Craft 3\\n\\nThe penalty for crafting without a workstation is reduced for you.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (88, 'Resourceful', 'Knowledge and Craft', '', 'Requirement: Craft 2 or Survival 2\\n\\nWhenever the GM would rule that you can salvage useful materials, you recover a little more than usual.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (89, 'Master Crafter', 'Knowledge and Craft', '', 'Requirement: Craft 4, Tricks of the Trade, Level 6\\n\\nChoose one craft field you selected for Tricks of the Trade. Re-roll 1d20 on the first related Craft test you make each scene.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (90, 'Eye for Detail', 'Knowledge and Craft', '', 'Requirement: Investigation 2\\n\\nTests to notice hidden compartments, tampering, weak points, or concealed details become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (91, 'Cryptographer', 'Knowledge and Craft', '', 'Requirement: Investigation 2, Lore 2\\n\\nTests to decode ciphers, break simple codes, and understand encoded writing become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (92, 'Polyglot', 'Knowledge and Craft', '', 'Requirement: Lore 2\\n\\nGain one additional language. You may take this perk multiple times.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (93, 'Bestiary', 'Knowledge and Craft', '', 'Requirement: Lore 2\\n\\nThe first time you encounter a creature type, you may ask the GM for one useful fact about its habits, weaknesses, or dangers.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (94, 'Historian', 'Knowledge and Craft', '', 'Requirement: Lore 2\\n\\nTests involving major historical events, dynasties, ruins, and old conflicts become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (95, 'Theologian', 'Knowledge and Craft', '', 'Requirement: Lore 2\\n\\nTests involving gods, cults, doctrine, sacred practices, and religious history become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (96, 'Anatomist', 'Knowledge and Craft', '', 'Requirement: Medicine 2 or Lore 2\\n\\nWhen you attack a living creature, the first hit you score each round deals 10% more damage.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (97, 'Cartographer', 'Knowledge and Craft', '', 'Requirement: Navigation 2\\n\\nWhen mapping a route, charting an area, or returning by a known path, re-roll 1d20 on the test.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (98, 'Seafarer', 'Knowledge and Craft', '', 'Requirement: Navigation 2\\n\\nNavigation tests at sea become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (99, 'Strong Back', 'Survival and Field', '', 'Requirement: Athletics 1\\n\\nIncrease your maximum Carry Weight by 10 kg.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (100, 'One with Water', 'Survival and Field', '', 'Requirement: Athletics 2\\n\\nTests for swimming become easier, and fighting in water hinders you less than normal.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (101, 'Charge', 'Survival and Field', '', 'Requirement: Athletics 3\\n\\nIf you move at least 3 hexes in a straight line before making a melee attack, that attack deals 10% more damage.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (102, 'Iron Grip', 'Survival and Field', '', 'Requirement: Athletics 4\\n\\nTests for climbing become easier, and you may re-roll 1d20 when resisting being disarmed.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (103, 'Evasive', 'Survival and Field', '', 'Requirement: Dexterity 6\\n\\nWhen you take Guard, gain +1 additional Deflection against the first attack that targets you before your next turn.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (104, 'Feline Grace', 'Survival and Field', '', 'Requirement: Dexterity 6, Athletics 2\\n\\nJumping, leaping, and landing safely become easier for you. Whenever you take falling damage, reduce the final damage by 10%.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (105, 'Mobile', 'Survival and Field', '', 'Requirement: Feline Grace, Level 4\\n\\nMoving through difficult terrain costs 1 less AP for you, to a minimum of 1.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (106, 'Faithful Companions', 'Survival and Field', '', 'Requirement: Animal Handling 2\\n\\nYou gain one animal companion approved by the GM. It is a loyal Beast that is weaker than a player character but useful in travel, scouting, or support.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (107, 'Strong Companions', 'Survival and Field', '', 'Requirement: Faithful Companions, Animal Handling 4, Level 5\\n\\nChoose one of your animal companions. It becomes stronger, tougher, or more capable in a way agreed with the GM.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (108, 'Part of the Pack', 'Survival and Field', '', 'Requirement: Animal Handling 2\\n\\nWhen you first encounter a non-hostile or uncertain Beast, you may attempt to calm it as a free social gesture before violence begins.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (109, 'Danger Detector', 'Survival and Field', '', 'Requirement: Survival 2 or Insight 2\\n\\nThe first test you make each scene to detect an ambush, trap, or obvious environmental hazard becomes easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (110, 'Hunter', 'Survival and Field', '', 'Requirement: Survival 2\\n\\nTests to track beasts, follow signs, and pursue prey become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (111, 'Forager', 'Survival and Field', '', 'Requirement: Survival 2\\n\\nForaging takes less time for you, and poor conditions hinder you less than normal.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (112, 'Survivalist', 'Survival and Field', '', 'Requirement: Survival 4\\n\\nYou can become Well-Rested in harsher conditions than most characters, so long as the location is not actively dangerous.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (113, 'Heavy Sleeper', 'Survival and Field', '', 'Requirement: Constitution 5\\n\\nOnce per full rest, you may ignore one source of interrupted sleep unless it is directly harmful.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (114, 'Know the Way', 'Survival and Field', '', 'Requirement: Navigation 3, Survival 2\\n\\nWhen leading a journey through land you have already crossed, the first Navigation or Survival test related to routefinding each day becomes easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (115, 'Field Medic', 'Medicine and Stealth', '', 'Requirement: Medicine 2\\n\\nTests to stabilize, bandage, or treat injuries in the field become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (116, 'Healer', 'Medicine and Stealth', '', 'Requirement: Medicine 3 or any magical identity perk\\n\\nWhenever you restore HP to another creature, add +1 healing.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (117, 'Defiance', 'Medicine and Stealth', '', 'Requirement: Resolve 2\\n\\nOnce per scene, re-roll 1d20 on a test to resist fear, despair, coercion, or magical influence.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (118, 'Lasting Focus', 'Medicine and Stealth', '', 'Requirement: Resolve 4\\n\\nThe first time each scene you would lose Concentration, reduce that loss by 1.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (119, 'Clarity', 'Medicine and Stealth', '', 'Requirement: Intelligence 6 or Resolve 6\\n\\nThe first Lore, Investigation, or Insight test you make each scene may be re-rolled.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (120, 'From the Shadows', 'Medicine and Stealth', '', 'Requirement: Stealth 2\\n\\nThe first attack you make against a creature that has not noticed you gains +1 Accuracy.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (121, 'Ghost', 'Medicine and Stealth', '', 'Requirement: From the Shadows, Stealth 4\\n\\nTests made to notice you become harder while you are hidden and stationary.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (122, 'Pickpocket', 'Medicine and Stealth', '', 'Requirement: Sleight of Hand 2\\n\\nTests to lift, plant, or palm a small object become easier.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (123, 'Deadly Ambush', 'Medicine and Stealth', '', 'Requirement: From the Shadows, Level 4\\n\\nThe first damaging hit you make against a creature that has not noticed you deals 20% more damage.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (124, 'Vanish', 'Medicine and Stealth', '', 'Requirement: Ghost, Level 7\\n\\nOnce per scene after you break line of sight, you may immediately attempt to hide without spending additional AP.', '');
INSERT OR IGNORE INTO perks (id, name, category, short_description, long_description, requirement_text) VALUES (125, 'Infiltrator', 'Medicine and Stealth', '', 'Requirement: Stealth 2, Sleight of Hand 2\\n\\nTests to bypass locks, simple security, or unnoticed entry become easier.', '');
