INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (4, 'The Quasarian Empire', '', '', 13);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (5, 'The Untamed Highlands', '', '', 14);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (6, 'Torgana Canyons', '', '', 15);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (7, 'Calatherian Principality', '', '', 16);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (8, 'Asharati Forest', '', '', 17);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (9, 'No Homeland', '', '', 18);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (10, 'Aratori Dominion', '', '', 19);
INSERT OR IGNORE INTO homelands (id, name, short_description, long_description, perk_id) VALUES (11, 'The Obsidian Desert', '', '', 20);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (1, 'Soldier', '', 'You have served with the military and gained hard training, discipline in the field, and a practical understanding of life on campaign.', 21, 2, 14);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (2, 'Criminal', '', 'You have lived by dishonorable means, learning to keep your hands quick, your presence hidden, and your face unreadable when trouble comes.', 22, 13, 10);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (3, 'Spy', '', 'Employed by a nation, order, or powerful interest, you have lived a life of infiltration and intrigue, learning how to read people, pass unnoticed, and become who others expect to see.', 23, 5, 11);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (4, 'Noble', '', 'You are part of a Noble family or have spent a significant portion of your life becoming one. Such a life comes with standing, expectation, and a deep familiarity with privilege and power.', 24, 11, 3);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (5, 'Farmer', '', 'You have lived a simple life close to the land. It has taught you how to care for animals, survive with little, and support others through steady practical work.', 25, 14, 1);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (6, 'Sage', '', 'You are a person of books, study, and careful thought. Whether broad in learning or deeply specialized, you have spent much of your life pursuing understanding.', 26, 7, 6);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (7, 'Acolyte', '', 'You are a person of faith. An acolyte''s life is spent learning modesty, doctrine, and the meanings behind rites, stories, and sacred practice.', 27, 7, 12);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (8, 'Entertainer', '', 'You have traveled, performed, and lived through the social currents of taverns, courts, festivals, and crowded roads. You know how to hold attention and how to read it.', 28, 12, 5);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (9, 'Artisan', '', 'You have spent much of your life honing a trade. Whether your work is rough or refined, you understand effort, repetition, and how to make something that lasts.', 29, 4, 2);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (10, 'Mercenary', '', 'You have sold your labor, your steel, or your courage where coin was offered. A mercenary learns to travel light, patch wounds, and survive without loyalty from anyone but those marching beside them.', 30, 2, 8);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (11, 'Pathfinder', '', 'You have spent your life helping others move through places without roads. You know how to read the land, keep your bearings, and move where others would get lost.', 31, 9, 14);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (12, 'Trader', '', 'You are familiar with the life on the road or sea and with the many people who make their living from exchange. A trader learns what things are worth, when to push, and when to walk away.', 32, 12, 11);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (13, 'Pirate', '', 'You have lived a pirate''s life of risk, shifting loyalties, sea travel, and surviving among dangerous crews and dangerous waters.', 33, 12, 9);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (14, 'Gladiator', '', 'You have lived by spectacle, violence, and surviving under the eyes of a crowd. A gladiator knows how to endure punishment and keep fighting when others would fold.', 34, 2, 5);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (15, 'Hunter', '', 'You are adept at tracking animals, stalking prey, and gathering what the wild has to offer. Your life has been shaped by patience, precision, and practical knowledge of living things.', 35, 1, 14);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (16, 'Elder', '', 'As an Elder of the tribe you possess more knowledge than most and are expected to offer wisdom when it is needed. Elder is a title of trust and understanding, not simply age.', 36, 7, 5);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (17, 'Beast Tamer', '', 'You have had the responsibility of taming, handling, and caring for the animals of your people. You understand their moods, needs, and dangers better than most.', 37, 1, 8);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (18, 'Dragon Knight', '', 'You were brought up at one of the holds of the Dragon Knight Order. Whether born to the order or taken in by it, your life has been shaped by dragon-hunting, discipline, and brutal duty.', 38, 2, 7);
INSERT OR IGNORE INTO backgrounds (id, name, short_description, long_description, perk_id, skill_id_1, skill_id_2) VALUES (19, 'Hermit', '', 'You have cast aside the stress of life among society in favor of solitude. Whether through contemplation, obsession, or withdrawal, you have learned how to live with very little.', 39, 14, 7);
