INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (1, 'Aimed Shot', '', 'Take the extra moment needed to place the attack exactly where you want it.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (2, 'Armor Knell', '', 'A hammer technique meant to punish even heavily protected foes.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (3, 'Battlefield Harvest', '', 'A dominating long bow technique that punishes anyone left exposed.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (4, 'Bell Ringer', '', 'A head-rattling hammer strike that leaves the target reeling.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (5, 'Black Comet', '', 'A spiked finishing strike that lands with terrifying inevitability.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (6, 'Blast Shot', '', 'Fire a broad close-range blast meant to overwhelm anything directly ahead.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (7, 'Boar Hunter', '', 'A spear finish meant to stop even a charging foe dead.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (8, 'Body Blow', '', 'A committed strike to the middle meant to steal breath and stance.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (9, 'Bolt Shot', '', 'Fire a bolt with simple force and reliability.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (10, 'Bone Crusher', '', 'A maul strike delivered with enough force to ruin whatever it lands on.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (11, 'Brace', '', 'A planted pike technique that turns the enemy''s momentum against them.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (12, 'Breach Bolt', '', 'Fire a reinforced shot meant to punch through protection and cover.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (13, 'Breach Shot', '', 'A devastating blast intended to tear through protection at close range.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (14, 'Breaker', '', 'A punishing finishing technique that turns leverage into raw harm.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (15, 'Center Mass', '', 'Aim for the largest opening and drive the shot through with force.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (16, 'Chain Snap', '', 'A violent flail motion that batters through timing and guard.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (17, 'Choke Hold', '', 'A dominating hold that shuts down the enemy''s options at close range.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (18, 'Chop', '', 'A heavy edged attack that commits to a decisive cut.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (19, 'Cleave', '', 'A wide committed swing intended to threaten more than one foe.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (20, 'Clinch', '', 'You crash in close and control the enemy''s space with your body.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (21, 'Clobber', '', 'A rough battering blow designed to knock the target off balance.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (22, 'Crater Maker', '', 'A hammer blow that lands with brutal finality.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (23, 'Crescent Arc', '', 'A flowing curved swing meant to catch multiple lines at once.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (24, 'Crippling Shot', '', 'Place the shot to hinder movement and break the target''s stride.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (25, 'Cross Cut', '', 'A disciplined follow-up that turns one opening into another.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (26, 'Deadeye', '', 'A perfectly measured pistol shot delivered with total confidence.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (27, 'Deadweight', '', 'Fire a punishing bolt that drags the target''s posture and momentum down.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (28, 'Drag Line', '', 'A controlling whip technique that tears through posture and positioning.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (29, 'Dragon Pin', '', 'The fullest expression of the arbalest: a monstrous bolt placed to stop even the hardest target.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (30, 'Draw Cut', '', 'A cut delivered as the blade moves free in one fluid motion.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (31, 'Drive', '', 'You step through the target with force to push them backward.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (32, 'Duelist''s End', '', 'A refined finishing attack that closes the fight cleanly.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (33, 'Eagle Eye', '', 'A long shot placed with exceptional clarity and control.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (34, 'Elbow', '', 'A brutal short-range strike delivered from tight positioning.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (35, 'Execution Line', '', 'A finishing firearm shot meant to end resistance immediately.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (36, 'Executioner''s Fall', '', 'A committed descending cut that ends hesitation and mercy.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (37, 'Falling Blossom', '', 'A graceful but lethal descending cut that completes the exchange.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (38, 'Falling Star', '', 'A great sword blow that carries the full arc of the weapon through the target.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (39, 'Fan the Hammer', '', 'Fire in rapid succession before the enemy can react cleanly.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (40, 'Feint', '', 'You bait a reaction before redirecting into the real attack.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (41, 'Field Breaker', '', 'A war bow shot meant to disrupt the enemy line through raw force.', 'Mastery');
