INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (43, 'Final Salute', '', 'A perfected rapier finish delivered with confidence and precision.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (44, 'Fire', '', 'Release a steady aimed shot from a long firearm.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (45, 'Flash Step', '', 'A sudden movement cut delivered before the target can reset.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (46, 'Flatten', '', 'A warhammer strike that turns weight and leverage into domination.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (47, 'Gash', '', 'A deeper deliberate wound intended to keep bleeding pressure on the target.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (48, 'Giant''s Sentence', '', 'A heavy finishing cut that leaves no room for recovery.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (49, 'Groundbreaker', '', 'A devastating impact that shakes bodies and footing alike.', 'Mastery');
