INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (94, 'Quiet Finish', '', 'A silent close shot that ends the exchange before it widens.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (95, 'Rain of Thorns', '', 'Layer an area with arrows so movement through it becomes dangerous.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (96, 'Reap', '', 'A broad harvesting swing that cuts through space in front of you.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (97, 'Red Horizon', '', 'A huge finishing cut that sweeps through everything before it.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (98, 'Rend', '', 'A savage tearing attack meant to open flesh and leave a lasting wound.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (99, 'Riposte', '', 'A sharp answer delivered the moment an opening appears.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (100, 'Rising Edge', '', 'An ascending blade path that turns defense into offense.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (101, 'Ruin Chain', '', 'A relentless chained assault that keeps the enemy from recovering space.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (102, 'Running Shot', '', 'Loose an arrow cleanly while still moving and repositioning.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (103, 'Sand Reaper', '', 'A cutting sequence meant to exhaust and carve the target down.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (104, 'Scatter Burst', '', 'Spread the blast wide to catch multiple targets in a dangerous space.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (105, 'Serpent''s Kiss', '', 'A precise whip finish that punishes the smallest mistake.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (106, 'Siege Line', '', 'A brutally committed arbalest shot made to break what others cannot.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (107, 'Silence Cut', '', 'A quiet finishing attack meant to end the fight before it can turn.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (108, 'Skewer', '', 'A long driving thrust meant to pin the target in place.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (109, 'Skull Crack', '', 'A crushing club strike meant to finish with blunt certainty.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (110, 'Slash', '', 'A simple cutting strike meant to pressure the target.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (111, 'Smash', '', 'A forceful basic blow meant to stagger through impact.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (112, 'Snap', '', 'A sharp cracking strike meant to disrupt timing and posture.', 'Proficiency');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (113, 'Snap Volley', '', 'Send several arrows skyward to threaten a wider area.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (114, 'Spinning Guard', '', 'A mastering flourish that attacks while controlling surrounding space.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (115, 'Split Guard', '', 'A disciplined axe strike that opens a target through broken defense.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (116, 'Split Shot', '', 'Fire with the intent of threatening more than one target or line at once.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (117, 'Stab', '', 'A direct forward thrust intended to keep the enemy at reach.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (118, 'Storm Volley', '', 'Fill an area with arrows and force everyone within it to react.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (119, 'Street Sweeper', '', 'The full brutal expression of a scatter gun in cramped fighting.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (120, 'Strike', '', 'A direct and reliable hit with the weapon''s weight or length.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (121, 'Suppressing Shot', '', 'Force the enemy to keep their head down and give up space.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (122, 'Sweep', '', 'A low or broad attack that takes away footing and space.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (123, 'Swing', '', 'A straightforward hammering attack with solid momentum.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (124, 'Thousand Cuts', '', 'A relentless series of shallow strikes that build pressure quickly.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (125, 'Thrust', '', 'A precise forward lunge aimed at a narrow opening.', 'Basic');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (126, 'Thunder Mouth', '', 'A concussive close-range discharge that leaves survivors reeling.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (127, 'Tomb Hammer', '', 'A full-bodied maul swing meant to end resistance outright.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (128, 'Twin Moon Cut', '', 'A flowing finishing pattern that strikes in a seamless pair.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (129, 'Twist', '', 'A precise turn of the weapon after contact to deepen the harm.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (130, 'Vaulting Blow', '', 'A mobile staff strike that turns movement into impact.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (131, 'Vein Hunter', '', 'A wickedly placed crossbow shot aimed at the most vulnerable point available.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (132, 'Wall Nailer', '', 'A heavy bolt that hammers the target into place with terrifying force.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (133, 'Whirling Step', '', 'A curving moving attack that changes angle mid-assault.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (134, 'Wing Clip', '', 'A strike meant to ruin footing and cut off clean movement.', 'Expertise');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (135, 'World Splitter', '', 'A great axe blow delivered with maximum force and commitment.', 'Mastery');
INSERT OR IGNORE INTO attacks (id, name, short_description, long_description, attack_tier) VALUES (136, 'Wrap', '', 'You curl the attack around the target to interfere with their position.', 'Expertise');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (1, 'Imbue Elements', '', '', 'Primal', 'Concentration,Elemental,Weapon', '1', '', 'Draw elemental force into a weapon. The weapon gains an elemental expression while the spell lasts. - Earth: The weapon strikes with crushing force and can Stun. - Air: The weapon becomes lighter and quicker in motion. - Water: The weapon gains freezing force and can apply Freeze. - Fire: The weapon gains Fire and can apply Burning.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (2, 'Conjure a Storm', '', '', 'Primal', 'Concentration,Weather', '1', 'C', 'Conjure a storm that obscures vision across a small area.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (3, 'Nature''s Balm', '', '', 'Primal', 'Healing,Poison', 'Varies', 'Reach', 'Conjure and apply a magical balm. The balm may heal, soothe, or poison depending on how it is prepared. - Healing: Restore Health over time. - Toxins: Deliver a poisonous attack through touch.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (4, 'Hunter''s Mark', '', '', 'Primal', 'Concentration,Hunt', '1', 'M', 'Mark a creature as prey. The spell makes the target easier to track over long distances and for a long duration.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (5, 'Control Plants', '', '', 'Primal', 'Concentration,Control,Nature', '1', 'C', 'Command nearby plants to lash out, restrain movement, and harm a creature.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (6, 'Commune with the Wild', '', '', 'Primal', 'Beast,Harmless,Lasting', '1', '', 'Call a nearby animal to you. It appears as a Normal creature and answers one question to the best of its knowledge.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (7, 'Shapeshift', '', '', 'Primal', 'Concentration,Transformation', '2', '', 'Transform into the form of a Normal animal. You gain the animal''s physical form and abilities while keeping your own maximum Health.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (8, 'Hunter''s Shot', '', '', 'Primal', 'Instant', '1', '', 'Empower one ranged weapon with primal force until the end of the scene.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (9, 'Exhale Fumes', '', '', 'Primal', 'Concentration,Hazard,Instant', '2', '', 'Exhale a cloud of dangerous fumes into the surrounding area. Creatures inside the fumes suffer damage.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (10, 'Sand Toss', '', '', 'Primal', 'Earth,Instant', 'Target Defense - 1', 'C', 'Control earth and sand to strike a target. The attack deals physical damage and can Stun.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (11, 'Control Water', '', '', 'Primal', 'Concentration,Water', '1', 'C', 'Take control of a quantity of free water and move it as you wish while the spell lasts.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (12, 'Regeneration', '', '', 'Primal', 'Concentration,Harmless,Healing', '2', 'M', 'Concentrate on a target and continuously heal its injuries and wounds. The target regains 3 CD at the start of each of your turns.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (13, 'Treant Form', '', '', 'Primal', 'Concentration,Harmless,Transformation', '2', 'Reach', 'Touch a target and grant it the power of the forest. Their skin hardens like bark, increasing protection and maximum Health.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (14, 'Counter Spell', '', '', 'Theoretical', 'Arcane,Harmless,Instant', '', '', 'Use this spell against an ongoing Channeling spell or an active Concentration spell. Roll d20 + Potency against Mana Spent x2. On a success, the target spell ends or fails, but the original caster still loses the Mana spent.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (15, 'Conjure Food and Drink', '', '', 'Theoretical', 'Conjuration,Harmless,Instant', '', '', 'Conjure a chosen food or drink item. The difficulty is based on the rarity of what you create.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (16, 'Conjure Weapon', '', '', 'Theoretical', 'Concentration,Conjuration,Weapon', '', '', 'Conjure a weapon from the normal equipment list. The weapon counts as magical, functions like a normal weapon, and begins with access to its Basic attack. The difficulty is based on the rarity of the weapon.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (17, 'Evoke Flame', '', '', 'Theoretical', 'Fire,Instant', 'Target Defense', 'M', 'Conjure flame in your hands and hurl it at a target. This spell deals 4 CD and applies Burning.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (18, 'Invoke Ice', '', '', 'Theoretical', 'Ice,Instant', 'Target Defense', 'C', 'Invoke ice in your hands and hurl it at a target. This spell deals 6 CD and applies Freeze.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (19, 'Levitate', '', '', 'Theoretical', 'Concentration,Harmless,Movement', '1', '', 'You levitate above the ground and drift rather than walk. While levitating, you are harder to strike in melee unless the attacker has suitable reach.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (20, 'Teleportation', '', '', 'Theoretical', 'Harmless,Instant,Movement', '1', 'M', 'Teleport yourself to a location within range that you can see.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (21, 'Necrotic Touch', '', '', 'Theoretical', 'Instant,Necrotic', 'Target Defense', 'Reach', 'Channel necrotic energy into your hand and deliver it through touch. On a successful cast, the touch deals 3 CD and applies Necrotic.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (22, 'Temper with Time', '', '', 'Theoretical', 'Concentration,Harmless,Time', '2', 'C', 'Temper with time around a creature to quicken or slow them. - Quickened: The target gains AP and acts with improved Speed for a short time. - Slow: The target loses AP and acts with worse Speed for a short time.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (23, 'Create Illusions', '', '', 'Theoretical', 'Concentration,Harmless,Illusion', '1', 'C', 'Create a visual illusion to mislead your enemies. A creature must spend an action to inspect the illusion and make a d20 + Investigation test against the caster''s Mind in order to see through it.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (24, 'Raise Dead', '', '', 'Theoretical', 'Concentration,Necrotic,Undead', '1', '', 'Raise and command undead servants. A single cast can safely raise either 1 Normal undead or 2 Minions without requiring a control check. Minions have a lower Mana cost than Normal undead. When you attempt to raise undead beyond that safe allowance, make a d20 + Potency check against your current control burden. Control burden begins at -5 and increases by the type of undead you control: - Minion: +2 - Normal: +5 - Mighty: +10 - Legendary: +15 If the check fails, the new undead is not raised and all undead already under your control break free. If you lose Concentration while controlling undead, make the same check to maintain control. On a failure, your undead break free. Undead remain under your control for a day unless laid to rest or otherwise released.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (25, 'Enslave', '', '', 'Theoretical', 'Concentration,Mind Control', 'Target Mind', 'C', 'Seize control of another creature''s will. On a success, you can command the target to carry out a safe and non-harmful act while you maintain Concentration.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (26, 'Arcane Ward', '', '', 'Theoretical', 'Concentration,Harmless,Ward', '1', '', 'Cast a ward over yourself that regenerates temporary Health. While concentrating, at the start of each of your turns you restore 3 CD temporary Health.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (27, 'Chaos Rays', '', '', 'Theoretical', 'Concentration,Necrotic,Radiant', '2', 'M', 'Unleash two rays. One heals 2 CD, and one deals 3 CD Necrotic damage. Choose a target for each. Anyone caught between the rays is affected when they cross or begin their turn in the line.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (28, 'Confusion', '', '', 'Theoretical', 'Concentration,Illusion,Mind', 'Target Mind', '', 'Cloud a creature''s thoughts until truth, order, and intention begin to fall apart. On a success, the target suffers a penalty to its defenses and becomes easier to mislead and disrupt.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (29, 'Aura of Conviction', '', '', 'Zealous', 'Concentration,Zealous', '2', '', 'Create an aura that follows you and fills your current area. The aura''s exact expression is shaped by your belief, oath, or divine allegiance. - Aura of Mercy: Divide 4 CD of healing among other creatures in the aura. - Aura of Judgment: Creatures within the aura that are already on the brink of death may be finished outright. - Aura of Revelation: Creatures within the aura are revealed. - Aura of Veils: Name an object and all instances of that object become harder to notice within the aura. - Aura of Beasts: Creatures with the Beast tag regard you as an ally. - Aura of Insight: Intelligence tests become easier within the aura. - Aura of Craft: Weapons within the aura become more reliable, and Craft tests within the aura become easier. - Aura of Wrath: Creatures damaged within the aura strike back harder on their next attack. - Aura of the Sentinel: Creatures have a harder time moving away from the center of the aura. - Aura of Flame: Weapons within the aura gain Fire. - Aura of Sand: You may strengthen or calm a sandstorm while the aura lasts.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (30, 'Divine Smite', '', '', 'Zealous', 'Instant,Weapon', '1', '', 'Brandish your weapon with sacred power for the next attack. The attack deals its normal damage plus 2 CD.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (31, 'Faithful Light', '', '', 'Zealous', 'Harmless,Instant', '1', 'C', 'Project a line of sacred light toward a target. When it reaches a creature, that creature regains 2 CD Health.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (32, 'Blessing', '', '', 'Zealous', 'Concentration,Harmless', '1', 'Reach', 'Bless another creature with divine favor. Increase one of that creature''s skills by 2, up to 8.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (33, 'Words of Power', '', '', 'Zealous', 'Instant', '3', 'C', 'Speak a word of power and surround yourself with sacred certainty. Gain +2 Deflection until the end of your next turn.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (34, 'Weapon of Faith', '', '', 'Zealous', 'Lasting,Zealous', '', '', 'Summon your weapon of faith. What form this weapon takes is determined by your belief. Unlike Conjure Weapon, you do not freely choose the weapon at cast time. It is the sacred weapon associated with your conviction, oath, or divine allegiance. While summoned, the weapon functions like a normal weapon from the equipment lists, but counts as magical. The exact weapon granted depends on your belief. Some beliefs grant only one sacred weapon, while others allow a small set of valid sacred weapons.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (35, 'Watchful Presence', '', '', 'Zealous', 'Concentration,Harmless', '2', 'C', 'Place a watchful presence over a creature. The next time that creature would fall to 0 Health, it instead returns to a small amount of Health after the attack resolves.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (36, 'Prayer of Protection', '', '', 'Zealous', 'Concentration,Harmless', '1', 'C', 'Pray for a god''s protection over two creatures of your choice. The targets ignore the first Effect applied to them each round.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (37, 'Restoration', '', '', 'Zealous', 'Concentration,Harmless', '3', 'Reach', 'Restore vital essence to a creature so it may live again. The spell revives a creature, but the restored life remains fragile while Concentration is maintained.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (38, 'Call for Aid', '', '', 'Zealous', 'Lasting,Zealous', '2', '', 'Call for aid from the servants, spirits, or followers tied to your belief. Summon one Normal ally from that domain until the end of the scene.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (39, 'Avatar of Conviction', '', '', 'Zealous', 'Concentration,Zealous', '3', '', 'Become the embodiment of your belief. Increase your Max Health by your level, increase weapon damage by 4 CD, gain immunity to Necrotic, and gain +3 Physical DT and +3 Magical DT. The spell lasts for 3 rounds and can extend itself through triumph.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (40, 'Condemn', '', '', 'Zealous', 'Concentration,Mind', 'Target Mind', '', 'Condemn another creature''s actions and flood it with guilt or certainty. On a success, the target can no longer Move or Sprint while the spell lasts.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (41, 'Cleansing Flame', '', '', 'Zealous', 'Concentration,Fire', 'Target Defense + 1', 'M', 'Engulf a target in a cleansing flame that persists while you maintain Concentration. At the start of each of your turns, the target takes 4 CD damage with Burning and Intense.');
INSERT OR IGNORE INTO spells (id, name, short_description, long_description, school, tags, difficulty, range_band, base_cast) VALUES (42, 'Glimmershards', '', '', 'Zealous', 'Instant,Radiant', '2', 'M', 'Throw three glimmershards. Each shard deals 1 CD and clings to the target. When that target is attacked, each attached shard explodes for additional damage.');
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (1, 1, 'Additional Element', '', '2 Mana', 'Imbue the weapon with an additional element.', 1);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (2, 1, 'Conjured Vessel', '', 'X + 1 Mana', 'Conjure a weapon to carry the chosen element.', 2);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (3, 1, 'Lasting Bond', '', '4 Mana', 'The elemental bond lasts until the end of the scene.', 3);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (4, 2, 'Blizzard', '', '2 Mana', 'The area becomes difficult terrain.', 1);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (5, 2, 'Vortex', '', '3 Mana', 'Creatures have difficulty escaping the storm''s pull.', 2);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (6, 2, 'Lightning', '', '4 Mana', 'Lightning strikes creatures within the storm and can Stun.', 3);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (7, 2, 'Widen Storm', '', '4 Mana', 'Increase the scale of the storm.', 4);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (8, 3, 'Curing', '', '4 Mana', 'Remove one poison, disease, or similar harmful condition.', 1);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (9, 3, 'Sickening', '', '3 Mana', 'The poisonous version also becomes Infectious.', 2);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (10, 3, 'Potent', '', '2 Mana', 'Increase the damage or healing.', 3);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (11, 3, 'Additional Portion', '', '1 Mana', 'Create an extra dose.', 4);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (12, 4, 'Strong Will', '', '2 Mana', 'Increase the duration.', 1);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (13, 4, 'Long Trail', '', '2 Mana', 'Increase the range.', 2);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (14, 4, 'Bleeding Mark', '', '2 Mana', 'Attacks against the marked creature can also inflict Bleeding.', 3);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (15, 5, 'Wall of Thorns', '', '4 Mana', 'Raise a thorn wall that harms creatures near it.', 1);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (16, 5, 'Decaying Touch', '', '2 Mana', 'Add Necrotic.', 2);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (17, 5, 'Poisonous Touch', '', '2 Mana', 'Add a poison condition.', 3);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (18, 6, 'More Ferocious', '', '5 Mana', 'The summoned animal is Mighty.', 1);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (19, 6, 'Legendary Beast', '', '7 Mana', 'The summoned animal is Legendary.', 2);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (20, 6, 'Sanctity of the Pack', '', '3 Mana', 'Summon an additional animal.', 3);
INSERT OR IGNORE INTO spell_variants (id, spell_id, name, short_description, mana_cost, long_description, ordinal_position) VALUES (21, 6, 'Assistance of the Wild', '', '2 Mana', 'Ask the animal to perform a practical task for you.', 4);
