INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (10, 'Blue Sparks', '', 'Blue sparks dance across your hands for a moment, but nothing else happens.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (11, 'Whispering Air', '', 'Nearby air whispers your last spoken word, but nothing else happens.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (12, 'No Strain', '', 'Nothing else happens.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (13, 'Scent of Rain', '', 'The air briefly smells of rain or ozone, but nothing else happens.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (14, 'No Strain', '', 'Nothing else happens.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (15, 'Faint Glow', '', 'Your eyes or skin glow faintly until the end of the turn, but nothing else happens.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (16, 'Arcane Trace', '', 'The spell leaves obvious magical signs behind until the end of the scene.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (17, 'Revealed Casting', '', 'You are easier to notice until the end of the scene.');
