INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (19, 'Flicker', '', 'Lose 1 AP after the spell resolves.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (20, 'Mana Leak', '', 'Lose 1 additional Mana after the spell resolves.');
