INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (22, 'Backlash', '', 'Take 2 HP damage.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (23, 'Jolted Nerves', '', 'Take 2 HP damage and reduce Concentration by 1.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (24, 'Spent Breath', '', 'You cannot gain Mana from Focus until the end of your next turn.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (25, 'Frayed Casting', '', 'Your next spell this scene has +1 Strain roll.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (26, 'Warped Spell', '', 'The GM slightly alters the spell''s appearance or exact expression.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (27, 'Loose Targeting', '', 'The GM may shift the spell''s target, area, or point of origin slightly.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (28, 'Hostile Echo', '', 'The spell creates a minor harmful side effect in the nearby area.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (29, 'Drain Burn', '', 'Take 3 HP damage and lose 1 additional Mana.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (30, 'Strain Burn', '', 'Take 4 HP damage and reduce Concentration by 2.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (31, 'Broken Focus', '', 'Your current spell resolves, but you cannot Focus until the end of the scene.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (32, 'Violent Miscast', '', 'The GM significantly alters the spell''s immediate outcome.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (33, 'Arcane Whiplash', '', 'Take 4 HP damage and lose all remaining AP.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (34, 'Rupture', '', 'Lose all remaining Mana and create an additional harmful magical side effect in the area.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (35, 'Cascading Failure', '', 'Roll on this table again once after resolving this result.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (36, 'Spell Collapse', '', 'The spell partially fails and lashes the caster with magical feedback. Take 5 HP damage.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (37, 'Open Conduit', '', 'The spell tears something open. The GM introduces an immediate dangerous magical phenomenon.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (38, 'Wild Surge', '', 'The spell resolves in a heavily distorted form chosen by the GM.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (39, 'Catastrophic Backlash', '', 'Take 6 HP damage, lose all remaining Mana, and reduce Concentration to 0.');
INSERT OR IGNORE INTO strain_table (roll_total, result_name, short_description, long_description) VALUES (40, 'Arcane Disaster', '', 'The spell catastrophically collapses. Take 6 HP damage, lose all remaining Mana, become Stunned for the round, and the GM creates a major magical consequence.');
