INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (1, '', 'Might reflects raw force. It is the strength behind a crushing blow, the power needed to haul equipment across a battlefield, and the bodily force that lets a character impose themselves on the world.', 'attributes', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (2, '', 'Dexterity measures speed, balance, flexibility, and bodily control. It governs how quickly you can act, how easily you avoid incoming attacks, and how sharply your body reacts to sudden danger.', 'attributes', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (3, '', 'Constitution measures bodily resilience. It is the deep reserve that lets a character remain standing, survive blood loss, and hold together when the body is pushed beyond what should be survivable.', 'attributes', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (4, '', 'Perception measures awareness and precision. It is the ability to notice a weakness in an enemy''s stance, recognize danger before it strikes, and place attacks exactly where they matter most.', 'attributes', 4);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (5, '', 'Intelligence reflects memory, reason, and applied thought. It is the attribute behind clever planning, understanding systems, and shaping knowledge into something useful.', 'attributes', 5);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (6, '', 'Resolve reflects inner drive, self-control, and force of spirit. It is what lets a person stay focused under pressure, endure fear, and continue acting when lesser people would falter.', 'attributes', 6);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (7, '', 'Calming wild animals. Training, guiding, and caring for domestic animals and companions.', 'skills', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (8, '', 'Lifting, climbing, swimming, running, jumping, pushing, and other feats of physical exertion.', 'skills', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (9, '', 'Issuing orders, coordinating allies, and asserting authority in tense situations.', 'skills', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (10, '', 'Creating, maintaining, and repairing structures, tools, mixtures, and devices.', 'skills', 4);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (11, '', 'Reading motives, recognizing patterns in behavior, and understanding what people are really feeling or intending.', 'skills', 5);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (12, '', 'Searching, noticing hidden things, examining scenes, and identifying weaknesses in plans, structures, or security.', 'skills', 6);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (13, '', 'Knowledge of history, magic, religion, cultures, creatures, and the wider world.', 'skills', 7);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (14, '', 'Treating wounds and injuries, diagnosing disease and poison, and understanding bodily harm.', 'skills', 8);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (15, '', 'Finding your way across land or sea, planning routes, and keeping direction in unfamiliar places.', 'skills', 9);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (16, '', 'Picking locks, handling delicate mechanisms, concealing small objects, and performing precise hand-work.', 'skills', 10);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (17, '', 'Understanding customs, class, law, trade, and how groups and institutions operate.', 'skills', 11);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (18, '', 'Persuading, deceiving, inspiring, negotiating, and otherwise influencing people through words.', 'skills', 12);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (19, '', 'Moving quietly, hiding yourself, masking your presence, and avoiding notice.', 'skills', 13);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (20, '', 'Finding shelter, water, and food, tracking creatures, enduring the wilds, and handling environmental dangers.', 'skills', 14);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (21, '', 'Represents a character''s ability to deflect direct melee and ranged attacks.', 'defenses', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (22, '', 'Represents a character''s ability to dodge area of effect attacks.', 'defenses', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (23, '', 'Represents resistance to bodily harm, force, poison, and disease.', 'defenses', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (24, '', 'Represents strength of mind and resistance to mental attack.', 'defenses', 4);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (25, '', 'A burning creature suffers ongoing fire damage until the flames are extinguished.', 'conditions', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (26, '', 'A poisoned creature is suffering from a toxin with penalties and duration based on the poison.', 'conditions', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (27, '', 'The creature crawls, ranged attackers suffer a penalty, and adjacent enemies gain an accuracy bonus.', 'conditions', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (28, '', 'Your kind-hearted and altruistic nature inspires and empowers your companions. When you assist another character, add your full relevant skill instead of half.', 'perks', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (29, '', 'Your people are shaped by hardship and do not break easily. When you suffer Trauma, you do not suffer the extra Concentration loss from it.', 'perks', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (30, '', 'High Elves naturally carry status and legitimacy in the eyes of many cultures. You gain +2 Renown, representing your higher standing within societies. Individual people may still feel however they wish about you.', 'perks', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (31, '', 'From the moment of birth, every Dwarf bears a rune etched into their body, signifying clan, heritage, and fate. Choose one of the following runes:
Explorer''s Rune - Whenever you roll on a loot table, roll twice and choose the outcome.
Magister''s Rune - You know one spell for free.
Artisan''s Rune - You gain +2 on tests when using something you made yourself.', 'perks', 4);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (32, '', 'Your small frame and quick instincts make it difficult to pin you down. When moving out of melee with only one opponent threatening you, the extra AP cost does not apply.', 'perks', 5);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (33, '', 'Forged in the heart of a volcano, your body grows magical obsidian patches. Roll a random location at character creation. That location is immune to damage while the obsidian patch remains. If that location suffers 2 Trauma, the patch is destroyed. It regrows after a week, when your Vitality is reset.', 'perks', 6);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (34, '', 'Living in harmony with nature, your diet is strictly herbivorous. You cannot safely eat meat; if you do, your Max Health is reduced by 25% until you have had a full night''s rest. You are immune to disease, and all other food gives you double benefit.', 'perks', 7);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (35, '', 'Life is harsh, and your people are shaped by enduring it. During each full rest, you may either heal one additional Injury or reduce the duration of one disease by an additional step.', 'perks', 8);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (36, '', 'Though still fully living people, Husk-Folk have been touched by necrosis so deeply that it no longer harms them as it does others. You are immune to necrotic damage. Instead, you heal the full amount of necrotic damage that would have been inflicted upon you.', 'perks', 9);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (37, '', 'Nothing Wasted. You know how to make use of what nature gives and what it takes.', 'perks', 10);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (38, '', 'Your upbringing in a refined kingdom grants you the manners and expectations of civilized life. In formal settings, you are treated with the respect due to proper station unless you give others reason not to.', 'perks', 11);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (39, '', 'You can increase your Survival rating by 1.5 when it comes to exposure to cold weather.', 'perks', 12);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (40, '', 'You can increase your Survival rating by 1.5 when it comes to exposure to hot weather. You can go an hour longer for every stage of Thirst and hot weather does not halve it.', 'perks', 13);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (41, '', 'Travel-related rules will favor your experience once those systems are in place.', 'perks', 14);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (42, '', 'Once per scene, you can completely ignore one attack that targets you.', 'perks', 15);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (43, '', 'Whenever you successfully salvage an area, you also gain a free roll on the Oddities and Valuables table.', 'perks', 16);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (44, '', 'When you encounter a creature with the Beast tag, it will never attack you on sight. Also gain 1 reroll on all Animal Handling tests.', 'perks', 17);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (45, '', 'You can become Well-Rested even when sleeping in rough conditions that would normally prevent it.', 'perks', 18);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (46, '', 'Necrotic damage cannot put you in a coma.', 'perks', 19);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (47, '', 'Foraging becomes easier anywhere.', 'perks', 20);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (48, '', 'During combat, you gain 1 additional AP each turn that can only be spent on movement.', 'perks', 21);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (49, '', 'You do not need lockpicks in order to pick a lock.', 'perks', 22);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (50, '', 'Your Renown is increased while you are undercover or disguised.', 'perks', 23);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (51, '', 'You are accustomed to status, ceremony, and access. In appropriate civilized settings, you can secure basic hospitality or an audience that others might need to work harder to obtain.', 'perks', 24);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (52, '', 'Food and shelter you provide can support one additional person.', 'perks', 25);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (53, '', 'First encounter with a creature gives bonus Bestiary', 'perks', 26);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (54, '', 'Followers of your faith tend to treat you as one of their own unless given reason not to.', 'perks', 27);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (55, '', 'People are more willing to feed, host, or hear you out after a performance.', 'perks', 28);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (56, '', 'Crafting uses fewer resources.', 'perks', 29);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (57, '', 'During each full rest, you may also remove 1 Fatigue if you have no remaining source causing it.', 'perks', 30);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (58, '', 'Navigation becomes easier when you are leading the route.', 'perks', 31);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (59, '', 'You can reroll 1d20 when browsing, and always gain a 10% discount.', 'perks', 32);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (60, '', 'You can reroll 1d20 on Navigation tests while at sea. You also always gain Well-Rested when sleeping on a ship.', 'perks', 33);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (61, '', 'The first time each combat you would become Prone, you may ignore it.', 'perks', 34);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (62, '', 'Foraging takes less time for you.', 'perks', 35);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (63, '', 'When you take time to advise another character, their next relevant test becomes easier.', 'perks', 36);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (64, '', 'You gain an Animal Handling perk.', 'perks', 37);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (65, '', 'Survival tests when tracking Dragons become easier. You may reroll 1d20 on every damaging attack against a Dragon. After killing a Dragon, local villages celebrate you as a hero and you sleep, drink, and eat for free for the next 3 days.', 'perks', 38);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (66, '', 'You require less comfort to become Well-Rested and are less affected by long periods without company.', 'perks', 39);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (67, '', 'Requirement: Level 2\\n\\nChoose one weapon type. You gain access to that weapon''s Proficiency attacks.', 'perks', 40);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (68, '', 'Requirement: Weapon Proficiency with the chosen weapon, Level 10\\n\\nChoose one weapon type in which you already have Weapon Proficiency. You gain access to that weapon''s Expertise attacks.', 'perks', 41);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (69, '', 'Requirement: Weapon Expertise with the chosen weapon, Level 15\\n\\nChoose one weapon type in which you already have Weapon Expertise. You gain access to that weapon''s Mastery attacks.', 'perks', 42);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (70, '', 'Requirement: Weapon Proficiency, Dexterity 6\\n\\nOnce per round, you may swap loadouts or ready a different weapon as a free action.', 'perks', 43);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (71, '', 'Requirement: Quick Swap, Level 4\\n\\nYou gain one additional weapon loadout.', 'perks', 44);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (72, '', 'Requirement: Dexterity 6\\n\\nWhen fighting with a one-handed weapon in each hand, the first off-hand attack you make each round costs 1 less AP.', 'perks', 45);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (73, '', 'Requirement: Dexterity 7, Weapon Proficiency with a one-handed melee weapon\\n\\nWhile wielding a single one-handed melee weapon and no shield, gain +1 Deflection.', 'perks', 46);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (74, '', 'Requirement: Duelist, Level 5\\n\\nThe first time each round a creature misses you with a melee attack, your next melee attack against that creature gains +1 Accuracy and deals 10% more damage.', 'perks', 47);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (75, '', 'Requirement: Perception 6\\n\\nOnce each round, you may re-roll 1d20 on an attack made with a weapon you have proficiency in.', 'perks', 48);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (76, '', 'Requirement: Accurate, Level 4\\n\\nWhen you make a ranged attack against a creature within the weapon''s normal range, gain +1 Accuracy.', 'perks', 49);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (77, '', 'Requirement: Center of Mass, Level 7\\n\\nThe first ranged attack you make each round gains +1 Crit Die size.', 'perks', 50);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (78, '', 'Requirement: Might 7\\n\\nYou can wield a two-handed melee weapon in one hand for the purpose of carrying or readying it, but you still need two hands to use its attacks unless another rule says otherwise.', 'perks', 51);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (79, '', 'Requirement: Might 6, Constitution 6\\n\\nCreatures provoke 1 additional AP to move out of your Reach.', 'perks', 52);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (80, '', 'Requirement: Might 7, Constitution 6, Level 5\\n\\nWhile in Heavy Load, gain +1 Physical DT.', 'perks', 53);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (81, '', 'Requirement: Resolve 6, Level 5\\n\\nWhen you damage a creature that currently has Concentration, reduce its Concentration by 1. This can only happen once per turn.', 'perks', 54);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (82, '', 'Requirement: Dexterity 6\\n\\nThe first Interact action you take each round costs 1 less AP, to a minimum of 1.', 'perks', 55);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (83, '', 'Requirement: Intelligence 6, Lore 2\\n\\nLearn Theoretical spells through study and observation, gaining permanent access to all spells recorded in your spellbook without needing preparation.', 'perks', 56);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (84, '', 'Requirement: Resolve 6\\n\\nGain spells from any school through deals, sacrifices, and narrative events, with your power shaped and potentially altered by your patron.', 'perks', 57);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (85, '', 'Requirement: Resolve 6, Speech 2 or Lore 2\\n\\nGain a fixed set of Zealous spells based on your chosen belief or drive, changing only if your conviction fundamentally shifts.', 'perks', 58);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (86, '', 'Requirement: Resolve 6, Survival 2 or Lore 2\\n\\nSelect a limited number of Primal spells after performing a ritual, allowing you to change your available spells during a full rest.', 'perks', 59);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (87, '', 'Requirement: Resolve 6\\n\\nChoose a magical keyword, such as Fire, Illusion, or Necrotic. You learn matching spells from any school, with a limited number of permanently known spells that grows as you level.', 'perks', 60);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (88, '', 'Requirement: Resolve 7\\n\\nIncrease your maximum Mana by 2.', 'perks', 61);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (89, '', 'Requirement: Any magical identity perk, Level 3\\n\\nTests made to notice your spellcasting become harder unless the spell is especially loud, bright, or destructive.', 'perks', 62);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (90, '', 'Requirement: Resolve 7, Level 4\\n\\nGain +1 Concentration.', 'perks', 63);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (91, '', 'Requirement: Any magical identity perk, Weapon Proficiency, Level 4\\n\\nChoose one weapon type you have Weapon Proficiency with. That weapon counts as a casting focus for you, and the first time each round you deal damage with it you gain 1 Mana.', 'perks', 64);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (92, '', 'Requirement: Ability to deal Fire damage\\n\\nYou deal 10% more damage against targets that are on fire. If a single attack or spell affects more than one target that is on fire, increase the damage by an additional 10% for each extra burning target, up to 30% total.', 'perks', 65);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (93, '', 'Requirement: Ability to deal Fire damage\\n\\nThe first time each round you deal Fire damage, you may re-roll 1d20 on one Fire-related damage or effect roll tied to that action. If the table does not use such a roll, that attack or spell instead deals 10% more damage.', 'perks', 66);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (94, '', 'Requirement: Ability to deal Freeze damage or use Ice magic\\n\\nCreatures affected by your Ice or Freeze effects are easier to keep controlled. The first time each round you inflict Freeze, the target also loses 1 AP.', 'perks', 67);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (95, '', 'Requirement: Ability to deal Necrotic damage\\n\\nWhen you deal Necrotic damage, ignore 1 Necrotic DT.', 'perks', 68);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (96, '', 'Requirement: Perception 6\\n\\nWhenever one of your attacks scores a critical hit, gain 1 Mana.', 'perks', 69);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (97, '', 'Requirement: Deliberate Strikes, Perception 8, Level 8\\n\\nWhen one of your Crit Dice rolls its highest value, roll one additional Crit Die of the same size and add it. Dice generated by this perk cannot generate further Crit Dice.', 'perks', 70);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (98, '', 'Requirement: Might 6 or Resolve 6\\n\\nWhen you deal 5 or more HP damage with a single attack or spell, gain 1 Mana. If you deal 10 or more HP damage, gain 2 Mana instead. You cannot gain more than 2 Mana per turn from this perk.', 'perks', 71);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (99, '', 'Requirement: Resolve 6, Level 4\\n\\nWhen you suffer 5 or more HP damage from a single source, gain 1 Mana. If you suffer 10 or more HP damage, gain 2 Mana instead. You cannot gain more than 2 Mana per turn from this perk.', 'perks', 72);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (100, '', 'Requirement: Command 2\\n\\nOnce per scene, when combat begins, one ally who can hear you gains +1 AP on their first turn.', 'perks', 73);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (101, '', 'Requirement: Command 3, Resolve 6\\n\\nWhen you Assist an ally, they may use your full Command rank instead of half your skill bonus.', 'perks', 74);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (102, '', 'Requirement: Born Leader, Command 5, Level 6\\n\\nThe first time each scene you give an ally a direct order in a tense situation, their next relevant test becomes easier.', 'perks', 75);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (103, '', 'Requirement: Might 6 or Command 2\\n\\nWhen you try to intimidate a creature, you may use Might instead of Speech if your threat is based on force or physical menace.', 'perks', 76);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (104, '', 'Requirement: Insight 2\\n\\nWhen you enter a social scene, you may ask the GM for the dominant mood, pressure, or tension in the room.', 'perks', 77);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (105, '', 'Requirement: Insight 3\\n\\nTests to notice lies, fear, hidden hostility, or hesitation become easier for you.', 'perks', 78);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (106, '', 'Requirement: Speech 2\\n\\nOnce per scene, when you try to calm panic, defuse conflict, or stop a rash decision, re-roll 1d20 on the test.', 'perks', 79);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (107, '', 'Requirement: Speech 2, Society 2\\n\\nWhen you negotiate prices, gain a 10% discount on ordinary legal goods unless a stronger rule already applies.', 'perks', 80);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (108, '', 'Requirement: Speech 3, Society 3\\n\\nIn formal negotiations, the first failed Speech or Society test you make each scene may be re-rolled.', 'perks', 81);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (109, '', 'Requirement: Society 2\\n\\nIn courts, guilds, temples, or other structured groups, you are better at identifying who really holds influence.', 'perks', 82);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (110, '', 'Requirement: Society 3\\n\\nIf you have positive Renown in the current culture or faction, gain +2 on your first related social test each scene.', 'perks', 83);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (111, '', 'Requirement: Society 2 or Stealth 2\\n\\nTests made to find illegal, hidden, or restricted goods become easier.', 'perks', 84);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (112, '', 'Requirement: Society 2 or Stealth 2\\n\\nWhen trying to pass as part of a crowd, workplace, or social function, the first test to challenge your presence becomes harder.', 'perks', 85);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (113, '', 'Requirement: Craft 2\\n\\nChoose one field of craft such as alchemy, smithing, bowyering, tailoring, tinkering, or writing. Tests in that field become easier.', 'perks', 86);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (114, '', 'Requirement: Craft 3\\n\\nThe penalty for crafting without a workstation is reduced for you.', 'perks', 87);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (115, '', 'Requirement: Craft 2 or Survival 2\\n\\nWhenever the GM would rule that you can salvage useful materials, you recover a little more than usual.', 'perks', 88);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (116, '', 'Requirement: Craft 4, Tricks of the Trade, Level 6\\n\\nChoose one craft field you selected for Tricks of the Trade. Re-roll 1d20 on the first related Craft test you make each scene.', 'perks', 89);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (117, '', 'Requirement: Investigation 2\\n\\nTests to notice hidden compartments, tampering, weak points, or concealed details become easier.', 'perks', 90);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (118, '', 'Requirement: Investigation 2, Lore 2\\n\\nTests to decode ciphers, break simple codes, and understand encoded writing become easier.', 'perks', 91);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (119, '', 'Requirement: Lore 2\\n\\nGain one additional language. You may take this perk multiple times.', 'perks', 92);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (120, '', 'Requirement: Lore 2\\n\\nThe first time you encounter a creature type, you may ask the GM for one useful fact about its habits, weaknesses, or dangers.', 'perks', 93);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (121, '', 'Requirement: Lore 2\\n\\nTests involving major historical events, dynasties, ruins, and old conflicts become easier.', 'perks', 94);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (122, '', 'Requirement: Lore 2\\n\\nTests involving gods, cults, doctrine, sacred practices, and religious history become easier.', 'perks', 95);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (123, '', 'Requirement: Medicine 2 or Lore 2\\n\\nWhen you attack a living creature, the first hit you score each round deals 10% more damage.', 'perks', 96);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (124, '', 'Requirement: Navigation 2\\n\\nWhen mapping a route, charting an area, or returning by a known path, re-roll 1d20 on the test.', 'perks', 97);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (125, '', 'Requirement: Navigation 2\\n\\nNavigation tests at sea become easier.', 'perks', 98);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (126, '', 'Requirement: Athletics 1\\n\\nIncrease your maximum Carry Weight by 10 kg.', 'perks', 99);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (127, '', 'Requirement: Athletics 2\\n\\nTests for swimming become easier, and fighting in water hinders you less than normal.', 'perks', 100);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (128, '', 'Requirement: Athletics 3\\n\\nIf you move at least 3 hexes in a straight line before making a melee attack, that attack deals 10% more damage.', 'perks', 101);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (129, '', 'Requirement: Athletics 4\\n\\nTests for climbing become easier, and you may re-roll 1d20 when resisting being disarmed.', 'perks', 102);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (130, '', 'Requirement: Dexterity 6\\n\\nWhen you take Guard, gain +1 additional Deflection against the first attack that targets you before your next turn.', 'perks', 103);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (131, '', 'Requirement: Dexterity 6, Athletics 2\\n\\nJumping, leaping, and landing safely become easier for you. Whenever you take falling damage, reduce the final damage by 10%.', 'perks', 104);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (132, '', 'Requirement: Feline Grace, Level 4\\n\\nMoving through difficult terrain costs 1 less AP for you, to a minimum of 1.', 'perks', 105);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (133, '', 'Requirement: Animal Handling 2\\n\\nYou gain one animal companion approved by the GM. It is a loyal Beast that is weaker than a player character but useful in travel, scouting, or support.', 'perks', 106);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (134, '', 'Requirement: Faithful Companions, Animal Handling 4, Level 5\\n\\nChoose one of your animal companions. It becomes stronger, tougher, or more capable in a way agreed with the GM.', 'perks', 107);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (135, '', 'Requirement: Animal Handling 2\\n\\nWhen you first encounter a non-hostile or uncertain Beast, you may attempt to calm it as a free social gesture before violence begins.', 'perks', 108);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (136, '', 'Requirement: Survival 2 or Insight 2\\n\\nThe first test you make each scene to detect an ambush, trap, or obvious environmental hazard becomes easier.', 'perks', 109);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (137, '', 'Requirement: Survival 2\\n\\nTests to track beasts, follow signs, and pursue prey become easier.', 'perks', 110);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (138, '', 'Requirement: Survival 2\\n\\nForaging takes less time for you, and poor conditions hinder you less than normal.', 'perks', 111);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (139, '', 'Requirement: Survival 4\\n\\nYou can become Well-Rested in harsher conditions than most characters, so long as the location is not actively dangerous.', 'perks', 112);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (140, '', 'Requirement: Constitution 5\\n\\nOnce per full rest, you may ignore one source of interrupted sleep unless it is directly harmful.', 'perks', 113);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (141, '', 'Requirement: Navigation 3, Survival 2\\n\\nWhen leading a journey through land you have already crossed, the first Navigation or Survival test related to routefinding each day becomes easier.', 'perks', 114);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (142, '', 'Requirement: Medicine 2\\n\\nTests to stabilize, bandage, or treat injuries in the field become easier.', 'perks', 115);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (143, '', 'Requirement: Medicine 3 or any magical identity perk\\n\\nWhenever you restore HP to another creature, add +1 healing.', 'perks', 116);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (144, '', 'Requirement: Resolve 2\\n\\nOnce per scene, re-roll 1d20 on a test to resist fear, despair, coercion, or magical influence.', 'perks', 117);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (145, '', 'Requirement: Resolve 4\\n\\nThe first time each scene you would lose Concentration, reduce that loss by 1.', 'perks', 118);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (146, '', 'Requirement: Intelligence 6 or Resolve 6\\n\\nThe first Lore, Investigation, or Insight test you make each scene may be re-rolled.', 'perks', 119);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (147, '', 'Requirement: Stealth 2\\n\\nThe first attack you make against a creature that has not noticed you gains +1 Accuracy.', 'perks', 120);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (148, '', 'Requirement: From the Shadows, Stealth 4\\n\\nTests made to notice you become harder while you are hidden and stationary.', 'perks', 121);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (149, '', 'Requirement: Sleight of Hand 2\\n\\nTests to lift, plant, or palm a small object become easier.', 'perks', 122);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (150, '', 'Requirement: From the Shadows, Level 4\\n\\nThe first damaging hit you make against a creature that has not noticed you deals 20% more damage.', 'perks', 123);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (151, '', 'Requirement: Ghost, Level 7\\n\\nOnce per scene after you break line of sight, you may immediately attempt to hide without spending additional AP.', 'perks', 124);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (152, '', 'Requirement: Stealth 2, Sleight of Hand 2\\n\\nTests to bypass locks, simple security, or unnoticed entry become easier.', 'perks', 125);
