INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (173, '', 'You have served with the military and gained hard training, discipline in the field, and a practical understanding of life on campaign.', 'backgrounds', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (174, '', 'You have lived by dishonorable means, learning to keep your hands quick, your presence hidden, and your face unreadable when trouble comes.', 'backgrounds', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (175, '', 'Employed by a nation, order, or powerful interest, you have lived a life of infiltration and intrigue, learning how to read people, pass unnoticed, and become who others expect to see.', 'backgrounds', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (176, '', 'You are part of a Noble family or have spent a significant portion of your life becoming one. Such a life comes with standing, expectation, and a deep familiarity with privilege and power.', 'backgrounds', 4);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (177, '', 'You have lived a simple life close to the land. It has taught you how to care for animals, survive with little, and support others through steady practical work.', 'backgrounds', 5);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (178, '', 'You are a person of books, study, and careful thought. Whether broad in learning or deeply specialized, you have spent much of your life pursuing understanding.', 'backgrounds', 6);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (179, '', 'You are a person of faith. An acolyte''s life is spent learning modesty, doctrine, and the meanings behind rites, stories, and sacred practice.', 'backgrounds', 7);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (180, '', 'You have traveled, performed, and lived through the social currents of taverns, courts, festivals, and crowded roads. You know how to hold attention and how to read it.', 'backgrounds', 8);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (181, '', 'You have spent much of your life honing a trade. Whether your work is rough or refined, you understand effort, repetition, and how to make something that lasts.', 'backgrounds', 9);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (182, '', 'You have sold your labor, your steel, or your courage where coin was offered. A mercenary learns to travel light, patch wounds, and survive without loyalty from anyone but those marching beside them.', 'backgrounds', 10);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (183, '', 'You have spent your life helping others move through places without roads. You know how to read the land, keep your bearings, and move where others would get lost.', 'backgrounds', 11);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (184, '', 'You are familiar with the life on the road or sea and with the many people who make their living from exchange. A trader learns what things are worth, when to push, and when to walk away.', 'backgrounds', 12);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (185, '', 'You have lived a pirate''s life of risk, shifting loyalties, sea travel, and surviving among dangerous crews and dangerous waters.', 'backgrounds', 13);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (186, '', 'You have lived by spectacle, violence, and surviving under the eyes of a crowd. A gladiator knows how to endure punishment and keep fighting when others would fold.', 'backgrounds', 14);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (187, '', 'You are adept at tracking animals, stalking prey, and gathering what the wild has to offer. Your life has been shaped by patience, precision, and practical knowledge of living things.', 'backgrounds', 15);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (188, '', 'As an Elder of the tribe you possess more knowledge than most and are expected to offer wisdom when it is needed. Elder is a title of trust and understanding, not simply age.', 'backgrounds', 16);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (189, '', 'You have had the responsibility of taming, handling, and caring for the animals of your people. You understand their moods, needs, and dangers better than most.', 'backgrounds', 17);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (190, '', 'You were brought up at one of the holds of the Dragon Knight Order. Whether born to the order or taken in by it, your life has been shaped by dragon-hunting, discipline, and brutal duty.', 'backgrounds', 18);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (191, '', 'You have cast aside the stress of life among society in favor of solitude. Whether through contemplation, obsession, or withdrawal, you have learned how to live with very little.', 'backgrounds', 19);
