INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (352, '', 'Draw elemental force into a weapon. The weapon gains an elemental expression while the spell lasts. - Earth: The weapon strikes with crushing force and can Stun. - Air: The weapon becomes lighter and quicker in motion. - Water: The weapon gains freezing force and can apply Freeze. - Fire: The weapon gains Fire and can apply Burning.', 'spells', 1);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (353, '', 'Conjure a storm that obscures vision across a small area.', 'spells', 2);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (354, '', 'Conjure and apply a magical balm. The balm may heal, soothe, or poison depending on how it is prepared. - Healing: Restore Health over time. - Toxins: Deliver a poisonous attack through touch.', 'spells', 3);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (355, '', 'Mark a creature as prey. The spell makes the target easier to track over long distances and for a long duration.', 'spells', 4);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (356, '', 'Command nearby plants to lash out, restrain movement, and harm a creature.', 'spells', 5);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (357, '', 'Call a nearby animal to you. It appears as a Normal creature and answers one question to the best of its knowledge.', 'spells', 6);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (358, '', 'Transform into the form of a Normal animal. You gain the animal''s physical form and abilities while keeping your own maximum Health.', 'spells', 7);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (359, '', 'Empower one ranged weapon with primal force until the end of the scene.', 'spells', 8);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (360, '', 'Exhale a cloud of dangerous fumes into the surrounding area. Creatures inside the fumes suffer damage.', 'spells', 9);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (361, '', 'Control earth and sand to strike a target. The attack deals physical damage and can Stun.', 'spells', 10);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (362, '', 'Take control of a quantity of free water and move it as you wish while the spell lasts.', 'spells', 11);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (363, '', 'Concentrate on a target and continuously heal its injuries and wounds. The target regains 3 CD at the start of each of your turns.', 'spells', 12);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (364, '', 'Touch a target and grant it the power of the forest. Their skin hardens like bark, increasing protection and maximum Health.', 'spells', 13);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (365, '', 'Use this spell against an ongoing Channeling spell or an active Concentration spell. Roll d20 + Potency against Mana Spent x2. On a success, the target spell ends or fails, but the original caster still loses the Mana spent.', 'spells', 14);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (366, '', 'Conjure a chosen food or drink item. The difficulty is based on the rarity of what you create.', 'spells', 15);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (367, '', 'Conjure a weapon from the normal equipment list. The weapon counts as magical, functions like a normal weapon, and begins with access to its Basic attack. The difficulty is based on the rarity of the weapon.', 'spells', 16);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (368, '', 'Conjure flame in your hands and hurl it at a target. This spell deals 4 CD and applies Burning.', 'spells', 17);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (369, '', 'Invoke ice in your hands and hurl it at a target. This spell deals 6 CD and applies Freeze.', 'spells', 18);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (370, '', 'You levitate above the ground and drift rather than walk. While levitating, you are harder to strike in melee unless the attacker has suitable reach.', 'spells', 19);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (371, '', 'Teleport yourself to a location within range that you can see.', 'spells', 20);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (372, '', 'Channel necrotic energy into your hand and deliver it through touch. On a successful cast, the touch deals 3 CD and applies Necrotic.', 'spells', 21);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (373, '', 'Temper with time around a creature to quicken or slow them. - Quickened: The target gains AP and acts with improved Speed for a short time. - Slow: The target loses AP and acts with worse Speed for a short time.', 'spells', 22);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (374, '', 'Create a visual illusion to mislead your enemies. A creature must spend an action to inspect the illusion and make a d20 + Investigation test against the caster''s Mind in order to see through it.', 'spells', 23);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (375, '', 'Raise and command undead servants. A single cast can safely raise either 1 Normal undead or 2 Minions without requiring a control check. Minions have a lower Mana cost than Normal undead. When you attempt to raise undead beyond that safe allowance, make a d20 + Potency check against your current control burden. Control burden begins at -5 and increases by the type of undead you control: - Minion: +2 - Normal: +5 - Mighty: +10 - Legendary: +15 If the check fails, the new undead is not raised and all undead already under your control break free. If you lose Concentration while controlling undead, make the same check to maintain control. On a failure, your undead break free. Undead remain under your control for a day unless laid to rest or otherwise released.', 'spells', 24);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (376, '', 'Seize control of another creature''s will. On a success, you can command the target to carry out a safe and non-harmful act while you maintain Concentration.', 'spells', 25);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (377, '', 'Cast a ward over yourself that regenerates temporary Health. While concentrating, at the start of each of your turns you restore 3 CD temporary Health.', 'spells', 26);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (378, '', 'Unleash two rays. One heals 2 CD, and one deals 3 CD Necrotic damage. Choose a target for each. Anyone caught between the rays is affected when they cross or begin their turn in the line.', 'spells', 27);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (379, '', 'Cloud a creature''s thoughts until truth, order, and intention begin to fall apart. On a success, the target suffers a penalty to its defenses and becomes easier to mislead and disrupt.', 'spells', 28);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (380, '', 'Create an aura that follows you and fills your current area. The aura''s exact expression is shaped by your belief, oath, or divine allegiance. - Aura of Mercy: Divide 4 CD of healing among other creatures in the aura. - Aura of Judgment: Creatures within the aura that are already on the brink of death may be finished outright. - Aura of Revelation: Creatures within the aura are revealed. - Aura of Veils: Name an object and all instances of that object become harder to notice within the aura. - Aura of Beasts: Creatures with the Beast tag regard you as an ally. - Aura of Insight: Intelligence tests become easier within the aura. - Aura of Craft: Weapons within the aura become more reliable, and Craft tests within the aura become easier. - Aura of Wrath: Creatures damaged within the aura strike back harder on their next attack. - Aura of the Sentinel: Creatures have a harder time moving away from the center of the aura. - Aura of Flame: Weapons within the aura gain Fire. - Aura of Sand: You may strengthen or calm a sandstorm while the aura lasts.', 'spells', 29);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (381, '', 'Brandish your weapon with sacred power for the next attack. The attack deals its normal damage plus 2 CD.', 'spells', 30);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (382, '', 'Project a line of sacred light toward a target. When it reaches a creature, that creature regains 2 CD Health.', 'spells', 31);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (383, '', 'Bless another creature with divine favor. Increase one of that creature''s skills by 2, up to 8.', 'spells', 32);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (384, '', 'Speak a word of power and surround yourself with sacred certainty. Gain +2 Deflection until the end of your next turn.', 'spells', 33);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (385, '', 'Summon your weapon of faith. What form this weapon takes is determined by your belief. Unlike Conjure Weapon, you do not freely choose the weapon at cast time. It is the sacred weapon associated with your conviction, oath, or divine allegiance. While summoned, the weapon functions like a normal weapon from the equipment lists, but counts as magical. The exact weapon granted depends on your belief. Some beliefs grant only one sacred weapon, while others allow a small set of valid sacred weapons.', 'spells', 34);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (386, '', 'Place a watchful presence over a creature. The next time that creature would fall to 0 Health, it instead returns to a small amount of Health after the attack resolves.', 'spells', 35);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (387, '', 'Pray for a god''s protection over two creatures of your choice. The targets ignore the first Effect applied to them each round.', 'spells', 36);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (388, '', 'Restore vital essence to a creature so it may live again. The spell revives a creature, but the restored life remains fragile while Concentration is maintained.', 'spells', 37);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (389, '', 'Call for aid from the servants, spirits, or followers tied to your belief. Summon one Normal ally from that domain until the end of the scene.', 'spells', 38);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (390, '', 'Become the embodiment of your belief. Increase your Max Health by your level, increase weapon damage by 4 CD, gain immunity to Necrotic, and gain +3 Physical DT and +3 Magical DT. The spell lasts for 3 rounds and can extend itself through triumph.', 'spells', 39);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (391, '', 'Condemn another creature''s actions and flood it with guilt or certainty. On a success, the target can no longer Move or Sprint while the spell lasts.', 'spells', 40);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (392, '', 'Engulf a target in a cleansing flame that persists while you maintain Concentration. At the start of each of your turns, the target takes 4 CD damage with Burning and Intense.', 'spells', 41);
INSERT OR IGNORE INTO keywords (id, short_description, long_description, table_name, foreign_id) VALUES (393, '', 'Throw three glimmershards. Each shard deals 1 CD and clings to the target. When that target is attacked, each attached shard explodes for additional damage.', 'spells', 42);
