INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (149, 'Backpack, Small', '', '', 'Utility', 'Wearer adds 3 x Might to maximum Carry Weight.', 30.0, 0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (150, 'Lockpick', '', '', 'Utility', 'Lockpick tests become easier. One bobby pin breaks per complication rolled.', 1.0, 0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (151, 'Medical Bag', '', '', 'Utility', 'Medicine tests become easier. When providing long-term care, allows care of up to 2 additional patients.', 300.0, 5.0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (152, 'Bandages', '', '', 'Utility', 'Heal +1 upon succeeding at the First Aid action. Also stops bleeding effects.', 1.0, 0.1);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (153, 'Lantern', '', '', 'Utility', 'Generates bright light within Close range, and dim light within Medium range.', 15.0, 1.0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (154, 'Lockpick Set', '', '', 'Utility', 'Lockpick tests become easier. After 3 complications, the set is broken.', 150.0, 1.0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (155, 'Torch', '', '', 'Utility', 'Generates bright light within Close range until the end of the current scene. Requires an Intelligence + Survival test to light, and repeated use makes this harder.', 10.0, 1.0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (156, 'Bedroll', '', '', 'Utility', 'Enables a character to become rested after sleeping outdoors.', 35.0, 4.0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (157, 'Hunting Trap', '', '', 'Utility', 'Place and hide a trap using Intelligence + Survival. Spotting the trap requires awareness and close inspection. When triggered, the trap makes an attack against the target''s defenses and inflicts physical damage to the legs.', 50.0, 10.0);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (158, 'Ink', '', '', 'Utility', 'Used to write documents and scrolls. Empty after 30 uses.', 5.0, 0.4);
