INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (160, 'Paper', '', '', 'Utility', 'Used to write documents and scrolls. Bought in stacks of 30.', 7.0, 0.1);
INSERT OR REPLACE INTO utilities (id, name, short_description, long_description, category, effect_text, cost, weight) VALUES (161, 'Manacles', '', '', 'Utility', 'A shackled target suffers the effects of injured arms, legs, or both depending on what has been restrained. They can be broken with a Might + Athletics test or unlocked by an ally with a Perception + Sleight of Hand test.', 28.0, 1.0);
